mapper.select:
SELECT * FROM pcd_space_member_table
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}

SELECT * FROM pcd_space_member_table
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
ORDER BY role DESC, joined_at ASC

mapper.update:
UPDATE pcd_space_member_table SET role = #{role}
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}

mapper.delete:
